package com.saasvoting.election.domain.model;

/** Types of vote offered when defining a ballot (RF-06, RI-5). */
public enum VoteType {
    /** One option among at least two options defined by the administrator. */
    SINGLE_CHOICE,
    /** Fixed options «Sí», «No» and «Abstención», generated by the system. */
    YES_NO_ABSTAIN
}
